import React from 'react';

function App() {
  return (
    <div className="app">
      <header className="app-header">
        <h1>Medical Atlas</h1>
      </header>
      <main>
        <p>Welcome to Medical Atlas - Your comprehensive medical reference</p>
      </main>
    </div>
  );
}

export default App;
